#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <linux/io_uring.h>

int main() {
    struct io_uring_params p;
    memset(&p, 0, sizeof(p));
    p.flags = IORING_SETUP_SQPOLL | IORING_SETUP_SQ_AFF;
    p.sq_thread_cpu = 4096; // A large value likely >= nr_cpu_ids

    int ret = syscall(__NR_io_uring_setup, 1, &p);
    if (ret < 0) {
        perror("io_uring_setup");
    } else {
        printf("io_uring_setup succeeeded (unexpected)\n");
        close(ret);
    }
    return 0;
}

